PRAGMA foreign_keys = ON;
CREATE TABLE `users` (`id` text PRIMARY KEY NOT NULL,`username` text NOT NULL,`password_hash` text NOT NULL,`display_name` text NOT NULL,`role` text NOT NULL CHECK (`role` IN ('admin','manager','cashier')),`active` integer DEFAULT 1 NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `uq_users_username` ON `users` (`username`);
CREATE TABLE `settings` (`key` text PRIMARY KEY NOT NULL,`value` text NOT NULL,`updated_by` text REFERENCES `users`(`id`) ON DELETE SET NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE `menu_categories` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`sort_order` integer DEFAULT 0 NOT NULL,`active` integer DEFAULT 1 NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `uq_menu_categories_name` ON `menu_categories` (`name`);
CREATE TABLE `menu_items` (`id` text PRIMARY KEY NOT NULL,`category_id` text NOT NULL REFERENCES `menu_categories`(`id`),`name` text NOT NULL,`description` text DEFAULT '' NOT NULL,`price_cents` integer NOT NULL CHECK (`price_cents` >= 0),`image_key` text,`image_url` text,`available` integer DEFAULT 1 NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_menu_items_category` ON `menu_items` (`category_id`);
CREATE TABLE `inventory_items` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`category` text NOT NULL,`quantity_base` integer DEFAULT 0 NOT NULL CHECK (`quantity_base` >= 0),`alert_quantity_base` integer DEFAULT 0 NOT NULL CHECK (`alert_quantity_base` >= 0),`unit_dimension` text NOT NULL CHECK (`unit_dimension` IN ('mass','volume','count')),`display_unit` text NOT NULL CHECK (`display_unit` IN ('g','kg','ml','L','piece','pack')),`cost_micros_per_base` integer DEFAULT 0 NOT NULL,`active` integer DEFAULT 1 NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `uq_inventory_items_name` ON `inventory_items` (`name`);
CREATE TABLE `recipes` (`menu_item_id` text NOT NULL REFERENCES `menu_items`(`id`) ON DELETE CASCADE,`inventory_item_id` text NOT NULL REFERENCES `inventory_items`(`id`),`quantity_base` integer NOT NULL CHECK (`quantity_base` > 0),`display_unit` text NOT NULL CHECK (`display_unit` IN ('g','kg','ml','L','piece','pack')),`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,PRIMARY KEY (`menu_item_id`,`inventory_item_id`));
CREATE INDEX `idx_recipes_inventory` ON `recipes` (`inventory_item_id`);
CREATE TABLE `restaurant_tables` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`capacity` integer NOT NULL CHECK (`capacity` > 0),`current_guests` integer DEFAULT 0 NOT NULL CHECK (`current_guests` >= 0 AND `current_guests` <= `capacity`),`status` text DEFAULT 'available' NOT NULL CHECK (`status` IN ('available','occupied','reserved')),`active` integer DEFAULT 1 NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `uq_restaurant_tables_name` ON `restaurant_tables` (`name`);
CREATE TABLE `reservations` (`id` text PRIMARY KEY NOT NULL,`customer_name` text NOT NULL,`guest_count` integer NOT NULL CHECK (`guest_count` > 0),`table_id` text NOT NULL REFERENCES `restaurant_tables`(`id`),`starts_at` text NOT NULL,`ends_at` text NOT NULL,`phone` text,`notes` text,`status` text DEFAULT 'upcoming' NOT NULL CHECK (`status` IN ('upcoming','seated','completed','cancelled','no_show')),`created_by` text NOT NULL REFERENCES `users`(`id`),`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_reservations_date_table` ON `reservations` (`starts_at`,`table_id`);
CREATE INDEX `idx_reservations_status` ON `reservations` (`status`);
CREATE TABLE `shifts` (`id` text PRIMARY KEY NOT NULL,`user_id` text NOT NULL REFERENCES `users`(`id`),`opened_at` text NOT NULL,`closed_at` text,`opening_cash_cents` integer NOT NULL,`closing_cash_cents` integer,`status` text DEFAULT 'open' NOT NULL CHECK (`status` IN ('open','closed')),`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_shifts_user_status` ON `shifts` (`user_id`,`status`);
CREATE INDEX `idx_shifts_opened_at` ON `shifts` (`opened_at`);
CREATE TABLE `orders` (`id` text PRIMARY KEY NOT NULL,`order_number` integer NOT NULL,`status` text DEFAULT 'draft' NOT NULL CHECK (`status` IN ('draft','finalized','refunded','cancelled')),`order_type` text NOT NULL CHECK (`order_type` IN ('dine_in','takeaway','delivery')),`table_id` text REFERENCES `restaurant_tables`(`id`) ON DELETE SET NULL,`shift_id` text NOT NULL REFERENCES `shifts`(`id`),`cashier_id` text NOT NULL REFERENCES `users`(`id`),`subtotal_cents` integer NOT NULL,`tax_cents` integer DEFAULT 0 NOT NULL,`total_cents` integer NOT NULL,`finalized_at` text,`refunded_at` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `uq_orders_number` ON `orders` (`order_number`);
CREATE INDEX `idx_orders_status_created` ON `orders` (`status`,`created_at`);
CREATE INDEX `idx_orders_shift` ON `orders` (`shift_id`);
CREATE TABLE `order_items` (`id` text PRIMARY KEY NOT NULL,`order_id` text NOT NULL REFERENCES `orders`(`id`) ON DELETE CASCADE,`menu_item_id` text NOT NULL REFERENCES `menu_items`(`id`),`item_name_snapshot` text NOT NULL,`quantity` integer NOT NULL CHECK (`quantity` > 0),`unit_price_cents` integer NOT NULL,`line_total_cents` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_order_items_order` ON `order_items` (`order_id`);
CREATE INDEX `idx_order_items_menu` ON `order_items` (`menu_item_id`);
CREATE TABLE `payments` (`id` text PRIMARY KEY NOT NULL,`order_id` text NOT NULL REFERENCES `orders`(`id`),`method` text NOT NULL CHECK (`method` IN ('cash','card','online')),`amount_cents` integer NOT NULL,`status` text NOT NULL CHECK (`status` IN ('captured','refunded','failed')),`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_payments_order` ON `payments` (`order_id`);
CREATE INDEX `idx_payments_created` ON `payments` (`created_at`);
CREATE TABLE `expenses` (`id` text PRIMARY KEY NOT NULL,`description` text NOT NULL,`category` text NOT NULL,`amount_cents` integer NOT NULL CHECK (`amount_cents` > 0),`paid_from` text NOT NULL CHECK (`paid_from` IN ('cash_drawer','owner')),`shift_id` text REFERENCES `shifts`(`id`),`expense_date` text NOT NULL,`created_by` text NOT NULL REFERENCES `users`(`id`),`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_expenses_date_source` ON `expenses` (`expense_date`,`paid_from`);
CREATE INDEX `idx_expenses_shift` ON `expenses` (`shift_id`);
CREATE TABLE `inventory_transactions` (`id` text PRIMARY KEY NOT NULL,`idempotency_key` text NOT NULL,`inventory_item_id` text NOT NULL REFERENCES `inventory_items`(`id`),`quantity_before_base` integer NOT NULL,`quantity_changed_base` integer NOT NULL,`quantity_after_base` integer NOT NULL,`transaction_type` text NOT NULL CHECK (`transaction_type` IN ('sale_consumption','manual_adjustment','purchase_restock','refund_restoration','waste','reset','correction')),`reason` text NOT NULL,`order_id` text REFERENCES `orders`(`id`),`order_item_id` text REFERENCES `order_items`(`id`),`menu_item_id` text REFERENCES `menu_items`(`id`),`user_id` text NOT NULL REFERENCES `users`(`id`),`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `uq_inventory_transactions_idempotency` ON `inventory_transactions` (`idempotency_key`);
CREATE INDEX `idx_inventory_transactions_item_created` ON `inventory_transactions` (`inventory_item_id`,`created_at`);
CREATE INDEX `idx_inventory_transactions_order` ON `inventory_transactions` (`order_id`);
CREATE TABLE `audit_log` (`id` text PRIMARY KEY NOT NULL,`actor_user_id` text REFERENCES `users`(`id`) ON DELETE SET NULL,`action` text NOT NULL,`entity_type` text NOT NULL,`entity_id` text,`metadata_json` text DEFAULT '{}' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_audit_log_created` ON `audit_log` (`created_at`);
CREATE INDEX `idx_audit_log_entity` ON `audit_log` (`entity_type`,`entity_id`);
PRAGMA optimize;
